import random
import string

def user_id_gen_by_user(num_chars, num_ids, seed=None):
    if seed is not None:
        random.seed(seed)
    characters = string.ascii_letters + string.digits
    ids = []
    for _ in range(num_ids):
        ids.append(''.join(random.choice(characters) for _ in range(num_chars)))
    return ids
